/// The points of a pass a checker sees, in the order the served build's recorder takes them (stage j: layer
/// layers + j): each stage's attention input rows and its stage's ring plane, its partial and gather, the MoE's input
/// rows, partial and gather; the streams and pre after the stages; the head's logits (this rank's columns); the drafts.
pub const Point = enum { attn_in, attn_ring, attn_out, attn_gather, moe_in, moe_out, moe_gather, stages_h, stages_pre, local, markov };

/// A checker of a pass's buffers between its steps (synchronized first by the checker): false stops the pass.
pub const Probe = struct {
    ctx: *anyopaque,
    at: *const fn (ctx: *anyopaque, what: Point, stage: usize, dev: u64) anyerror!bool,

    fn check(pb: ?Probe, what: Point, stage: usize, dev: u64) !void {
        const p = pb orelse return;
        if (!try p.at(p.ctx, what, stage, dev)) return error.DraftMismatch;
    }
};

/// An absorb_many item: a drafting stream's slot, its window rows' taps (bf16 [n, taps * D], contiguous rows) and the
/// window's first position.
pub const Item = struct { slot: usize, taps: u64, n: usize, start: usize };

/// The served sampler's keys of a pass's streams (TF_DS_T26_KEYED_DRAFT): each stream's seed and temperature (<= 0:
/// greedy, no noise). Draft j of a stream is keyed at q0 + 1 + j, the key the verify's sampler uses for that row.
pub const Keyed = struct { seeds: []const u64, temps: []const f64 };

/// The Markov loop's pre-step hook: step i's logits block row of every stream plus T * gumbel (each step reads its own
/// block row of `local`, so no noise reaches another step).
const NoiseTap = struct {
    e: *const Engine,
    dr: *const Drafter,
    n: usize,

    fn run(ctx: *anyopaque, step: usize) anyerror!void {
        const x: *NoiseTap = @ptrCast(@alignCast(ctx));
        const mk = x.dr.mk;
        const lw = mk.rowCols();
        try x.e.ops.keyedNoise(x.e.s, x.dr.local + 4 * step * lw, x.dr.bn * lw, lw, mk.col0(), x.dr.nz, step, x.n);
    }
};

/// TF_DS_SPEC_SAMPLE's step hook between the step's _bias and _score (tri_markov.stepsTapped's mid): every sampled
/// stream's clean scores (its logits plus the Markov bias row _score adds: the cached row of the token the step reads,
/// else the step's staging row) and their normaliser partials into `sq` (tf_ds_spec_clean_kernel), then NoiseTap's
/// keyed noise under the draft key, so each draft is a draw from softmax(clean / T) and the verify gathers its numbers.
const SpecTap = struct {
    e: *const Engine,
    dr: *const Drafter,
    n: usize,
    ts: usize,

    fn run(ctx: *anyopaque, step: usize) anyerror!void {
        const x: *SpecTap = @ptrCast(@alignCast(ctx));
        const dr = x.dr;
        const mk = dr.mk;
        const lw = mk.rowCols();
        try x.e.ops.specClean(x.e.s, dr.local + 4 * step * lw, dr.n * lw, lw, dr.nz, dr.out + 8 * step, x.ts, mk.slot, mk.cache, dr.msc.stage, mk.cols, dr.sq + 4 * step * dr.sq_w, dr.n * dr.sq_w, x.n);
        try x.e.ops.keyedNoise(x.e.s, dr.local + 4 * step * lw, dr.n * lw, lw, mk.col0(), dr.nz, step, x.n);
    }
};

/// TF_DS_SPEC_SAMPLE: the most rows a verify speculates (every stream's held drafts) and the most elements its gather

    };
    try prompt.fill(e, dr.msc.send, 0, max_streams * 4 * 4);
    dr.mg = try a.take(dr.mk.world * max_streams * 4 * 4);
    dr.out = try a.take(max_streams * (max_block + 1) * 8);
    dr.nz = if (e.ops.keyed_noise != null) try a.take(max_streams * @sizeOf(ops_mod.KeyedRow)) else 0;
    // TF_DS_SPEC_SAMPLE (dr starts undefined: these are set off too, or the off path reads stack bytes). TP2 or one
    // rank only: a 2D node's Markov quarter (TF_DS_2D_DRAFT_HEAD) and the four-node world are not built for it
    dr.sq = 0;
    dr.sq_w = 0;
    dr.gidx = 0;
    dr.gout = 0;
    dr.gpeer = 0;
    if (e.ops.spec) {
        if (e.two != null or e.world > 2 or dr.mk.cols != dr.mk.rowCols() or dr.nz == 0) return error.SpecSampleWorld;
        dr.sq_w = dr.mk.rowCols() + 2 * ops_mod.spec_parts;
        dr.sq = try a.take(R * dr.sq_w * 4);
        dr.gidx = try a.take(spec_elems * 8);
        dr.gout = try a.take(spec_elems * 4);
        dr.gpeer = try a.take(e.world * spec_elems * 4);
    }
    // the confidence head
    const rank = c.markov_rank;
    dr.embs = try a.take(R * rank * 2);
    dr.xcf = try a.take(R * d * 4);
    dr.ef = try a.take(R * rank * 4);
    dr.conf_in = try a.take(R * (d + rank) * 4);
    dr.confw = try a.take((d + rank) * 4);
    try e.ops.f16ToF32(e.s, ds.conf, dr.confw, d + rank);
    dr.conf = try a.take(R * 4);
    // absorbs
    const ring = c.window + ring_extra;
    dr.at = try a.take(ring * dr.taps_w * 2);
    dr.ay = try a.take(ring * d * 2);
    dr.ax = try a.take(ring * d * 2);
    dr.ak = @splat(0);
    for (0..ds.blocks.len) |j| dr.ak[j] = try a.take(ring * hd * 2);
    dr.ao = try a.take(ring * hd * 2);
    dr.apos = try a.take(ring * 8);
    dr.arows = try a.take(ring * 8);
    // TF_DS_LORA: the folder's adapter for this rank, or null (a bad folder fails the load here)
    dr.lora = try lora.load(e, a, sp, if (std.c.getenv(lora.env)) |v| std.mem.span(v) else null, max_rows);
    return dr;
}

fn row(dr: *const Drafter, i: usize) u64 {
    return dr.rows + i * max_rows * 8;
}

/// Drafter.absorb into slot `slot`'s view: the target's taps rows of positions start .. start + n - 1 (bf16
/// [n, taps * D], contiguous) into every stage's ring, the last ring rows of them: main_x = RMSNorm(main_proj @
/// taps), each stage's wkv of it normed and roped into its ring row (position % ring).
pub fn absorb(dr: *Drafter, e: *const Engine, ch: *const Chunk, pool: *Pool, slot: usize, taps: u64, n: usize, start: usize) !void {
    if (n == 0 or slot >= pool.slots) return error.BadAbsorb;
    const keep = @min(n, pool.ring);
    if (keep > 128) return notPorted(@src()); // main_proj's prompt GEMM (the served lane's replay keeps 128 rows)
    const first = start + n - keep;
    var pos: [max_absorb * 9]i64 = undefined;
    var rows: [max_absorb * 9]i64 = undefined;
    for (0..keep) |r| {
        pos[r] = @intCast(first + r);
        rows[r] = @intCast((first + r) % pool.ring);
    }
    try prompt.upload(e, dr.apos, &pos, keep * 8);
    try prompt.upload(e, dr.arows, &rows, keep * 8);
    try dr.mainKeys(e, ch, taps + (n - keep) * dr.taps_w * 2, keep);
    for (dr.ds.blocks, 0..) |lay, j| {
        try tri_norm.kvNormRope(e.t, dr.ak[j], lay.kv_norm, e.plain.cos, e.plain.sin, dr.apos, pool.view(j, slot), pool.ring, dr.arows, e.c.eps, true, e.c.rope_dim, dr.ao, keep, e.c.head_dim);
    }
    pool.absorbed[slot] = start + n;
}

/// Drafter.absorb_many: every item's rows in one pass over the pool's planes (ring row slot * ring + position %
/// ring); the caller sets each slot's `absorbed` (eager: the kept length, known after sampling).
pub fn absorbMany(dr: *Drafter, e: *const Engine, ch: *const Chunk, pool: *const Pool, items: []const Item) !void {
    var n: usize = 0;
    var pos: [max_absorb]i64 = undefined;
    var rows: [max_absorb]i64 = undefined;
    for (items) |it| {
        if (it.slot >= pool.slots or n + it.n > max_absorb) return error.BadAbsorb;
        try e.ops.copyRows(e.s, it.taps, dr.taps_w * 2, dr.at + n * dr.taps_w * 2, dr.taps_w * 2, dr.taps_w * 2, it.n);
        for (0..it.n) |r| {
            const p = it.start + r;
            pos[n + r] = @intCast(p);
            rows[n + r] = @intCast(it.slot * pool.ring + p % pool.ring);
        }
        n += it.n;
    }
    if (n == 0) return;
    try prompt.upload(e, dr.apos, &pos, n * 8);
    try prompt.upload(e, dr.arows, &rows, n * 8);
    try dr.mainKeys(e, ch, dr.at, n);
    for (dr.ds.blocks, 0..) |lay, j| {
        try tri_norm.kvNormRope(e.t, dr.ak[j], lay.kv_norm, e.plain.cos, e.plain.sin, dr.apos, pool.rings[j], pool.slots * pool.ring, dr.arows, e.c.eps, true, e.c.rope_dim, dr.ao, n, e.c.head_dim);
    }
}

/// main_x = RMSNorm(main_proj @ taps) of n rows, then every stage's wkv of it (stage_kv: one group).
fn mainKeys(dr: *Drafter, e: *const Engine, ch: *const Chunk, taps: u64, n: usize) !void {
    const c = e.c;
    const d = c.hidden;
    const hd = c.head_dim;
    try prompt.grouped(e, ch, n, &.{dr.ds.main_proj}, &.{taps}, &.{dr.taps_w}, &.{dr.ay}, &.{d}, &.{.bf16});
    try tri_basic.rmsnorm(e.t, dr.ay, d, dr.ds.main_norm, dr.ax, d, c.eps, n, d);
    const S = dr.ds.blocks.len;
    var ls: [max_stages]weights.Linear = undefined;
    var xs: [max_stages]u64 = undefined;
    var ldxs: [max_stages]usize = undefined;
    var ldos: [max_stages]usize = undefined;
    var types: [max_stages]exl3_linear.DType = undefined;
    for (dr.ds.blocks, 0..) |lay, j| {
        ls[j] = lay.wkv;
        xs[j] = dr.ax;
        ldxs[j] = d;
        ldos[j] = hd;
        types[j] = .bf16;
    }
    try prompt.grouped(e, ch, n, ls[0..S], xs[0..S], ldxs[0..S], dr.ak[0..S], ldos[0..S], types[0..S]);
}

/// A pass's block rows a stream for `steps` drafts: the checkpoint's block, or as many rows as drafts past it
/// (TF_DS_DRAFT_BLOCK; steps <= n_most).
pub fn blockRows(dr: *const Drafter, steps: usize) usize {
    return @max(dr.n, steps);
}

/// BatchDraftGraph.run for N streams (tokens at positions q0 in slots): each stream's `steps` drafts and their
/// confidences into drafts / confs. Each slot's rings hold its positions before q0 (absorbed).
pub fn pass(dr: *Drafter, e: *const Engine, ch: *const Chunk, pool: *const Pool, tokens: []const i64, q0: []const i64, slots: []const i64, steps: usize, probe: ?Probe, keyed: ?Keyed) !void {
    const N = tokens.len;
    if (steps == 0 or steps > dr.n_most) return error.BadDraftPass;
    const n = dr.blockRows(steps);
    const R = N * n;
    if (N == 0 or N > max_streams or R > max_rows or q0.len != N or slots.len != N) return notPorted(@src());
    dr.bn = n; // the body's (a captured pass's key is its streams and steps: its block rows follow from the steps)
    // _body's index rows: ids [token, noise ...], positions q0 + j, window positions q0 - 1, ring bases
    var hv: [6 * max_rows]i64 = @splat(0);
    var hb: [max_rows * pick_pad]i64 = @splat(-1);
    const bw: usize = if (R > tri.decode_rows) pick_pad else n; // the pick list's columns
    for (0..N) |i| {
        if (slots[i] < 0 or slots[i] >= pool.slots) return error.BadSlot;
        for (0..n) |j| {
            const r = i * n + j;
            hv[0 * max_rows + r] = if (j == 0) tokens[i] else dr.noise;
            hv[1 * max_rows + r] = q0[i] + @as(i64, @intCast(j));
            hv[2 * max_rows + r] = q0[i] - 1;
            hv[3 * max_rows + r] = slots[i] * @as(i64, @intCast(pool.ring));
            hv[4 * max_rows + r] = 0;
            hv[5 * max_rows + r] = -1;
            for (0..n) |k| hb[r * bw + k] = @intCast(i * n + k);
        }
    }
    try prompt.upload(e, dr.rows, &hv, hv.len * 8);
    try prompt.upload(e, dr.bidx, &hb, R * bw * 8);
    // the Markov loop's out [N, steps + 1]: each stream's last token first
    const ts = steps + 1;
    var ho: [max_streams * (max_block + 1)]i64 = @splat(0);
    for (0..N) |i| ho[i * ts] = tokens[i];
    try prompt.upload(e, dr.out, &ho, N * ts * 8);
    // the noise runs only in a pass with a sampled stream: all-greedy passes (and the flag off) launch what they did
    var noisy = false;
    if (keyed) |k| {
        if (k.seeds.len != N or k.temps.len != N) return error.BadDraftPass;
        var tab: [max_streams]ops_mod.KeyedRow = undefined;
        for (0..N) |i| {
            tab[i] = .{ .seed = k.seeds[i], .temp = k.temps[i], .pos = q0[i] + 1 };
            if (k.temps[i] > 0.0) noisy = true;
        }
        if (noisy) {
            if (dr.nz == 0) return error.KeyedDraftOff;
            try prompt.upload(e, dr.nz, &tab, N * @sizeOf(ops_mod.KeyedRow));
        }
    }
    if (dr.graphs != null and probe == null) try dr.graphs.?.run(dr, e, ch, pool, N, steps, noisy) else try dr.body(e, ch, pool, N, steps, probe, noisy);
    // one host read: the drafts and the confidences
    try e.s.synchronize();
    var hc: [max_streams * max_block]f32 = undefined;
    try e.d.check(e.d.api.cuMemcpyDtoH_v2(&ho, dr.out, N * ts * 8), "cuMemcpyDtoH");
    try e.d.check(e.d.api.cuMemcpyDtoH_v2(&hc, dr.conf, N * steps * 4), "cuMemcpyDtoH");
    for (0..N) |i| for (0..steps) |j| {
        dr.drafts[i][j] = ho[i * ts + 1 + j];
        dr.confs[i][j] = hc[i * steps + j];

}

/// TF_DS_KV_SHARD: the filling prompt's view (fillBegin's, at `base`) with its borrowed twins (`on`; `local`: this
/// rank's twin when it does not own the extent; prompt.Caches.twinned), or plain again. Both ranks bind at the
/// same frame (kv_lanes.zig), between chunks only.
pub fn bindTwin(m: *Model, base: usize, on: bool, local: ?usize) !void {
    const v = try m.caches.view(&m.eng, m.fill_slot, base);
    m.view = if (on) try v.twinned(&m.caches, &m.eng, base, local) else v;
}

/// The prompt's chunk of n rows from position `start` (seq: the stream's ids through the chunk's end) through every
/// layer with the served bounded replay (replay = the prompt's length - the window: an encoder-only chunk stops at
/// the decoder's first layer). A chunk that reaches the head leaves the logits of its last row in ch.head_g and,
/// drafting, its DSpark taps absorbed into the slot's drafter rings. True when it reached the head.
pub fn fillChunk(m: *Model, seq: []const i32, start: usize, n: usize, replay: usize) !bool {
    const end = try m.fillSlice(seq, .{ .start = start, .n = n, .replay = replay }, 0, m.eng.c.layers);
    return end == .head;
}

/// Layers [lo, hi) of a chunk: lo 0 starts the chunk (`args`, seq through its end, as fillChunk takes them), any
/// other lo continues the part-run chunk from the layer it stopped at. The slice that reaches the last layer (or
/// the replay cut of an encoder-only chunk) ends the chunk as fillChunk does. A failed slice leaves no chunk to resume.
pub fn fillSlice(m: *Model, seq: []const i32, args: ChunkArgs, lo: usize, hi: usize) !SliceEnd {
    return m.sliceRun(seq, args, lo, hi) catch |err| {
        m.rs.reset();
        return err;
    };
}

/// The part-run chunk's placement (null: none runs).
pub fn resumeArgs(m: *const Model) ?ChunkArgs {
    return if (m.rs.live) m.rs.args else null;
}

/// Forgets a part-run chunk, if one is.
pub fn dropChunk(m: *Model) void {
    if (m.rs.live) m.rs.reset();
}

fn openChunk(m: *Model, seq: []const i32, args: ChunkArgs) !void {
    const start = args.start;
    const n = args.n;
    if (n == 0 or n > chunk_rows or seq.len != start + n) return error.BadChunk;
    const e = &m.eng;
    const c = e.c;
    const ch = &m.ch;
    // an image position's id is negative in the sequence (its n-grams dead for Engram): its embedding's id is the
    // image token's, which its span row then replaces
    const image_id: i64 = if (c.image_token) |t| t else 0;
    for (0..n) |j| m.ids64[j] = if (seq[start + j] < 0) image_id else seq[start + j];
    const pt = m.ptimer;
    if (pt) |t| try t.mark(m.stream, .start);
    prefill_prof.mark(m.stream, .start);
    try prompt.begin(e, ch, m.ids64[0..n], start, m.host_pos);
    if (ch.spans.len > 0) try prompt.embedSpans(e, ch);
    if (pt) |t| try t.mark(m.stream, .embed);
    prefill_prof.mark(m.stream, .embed);
    // Engram rows read ahead on a thread while the GPU runs the layers before them (the served reader pool's
    // overlap): this chunk's both layers' during the chunk before it (m.ahead), else the first layer's from the
    // chunk's start and the next's once the first is applied
    var ahead: ?std.Thread = m.ahead;
    m.ahead = null;
    m.rs = .{ .live = true, .args = args };
    // TF_DS_EXACT_RESUME: this chunk's tail rows go to its slot's tail (fillBegin's; a resumed pass's prepend too)
    ch.tail = if (m.exact_resume) &m.tails[m.fill_slot] else null;
    if (m.eh) |*eh| ref: {
        // TF_DS_ENGRAM_LEAD: each layer's rows come from its own reader (engram_lead.zig), not the read-ahead below
        if (eh.lead_on) {
            m.lead.begin(eh, c, seq, start, n);
            break :ref;
        }
        if (ahead != null and (eh.ahead_start != start or eh.ahead_n != n)) {
            ahead.?.join();
            ahead = null;
        }
        // rows read ahead that ended before a round or a piece's end are this chunk's when they cover it, both layers
        const whole = eh.ahead_start == start and eh.ahead_n == n and eh.ahead_err == null and eh.ahead_ready[0] and (c.engram_layers.slice().len < 2 or eh.ahead_ready[1]);
        if (ahead == null and !whole) {
            eh.ahead_start = start;
            eh.ahead_n = n;
            eh.ahead_ready = .{ false, false };
            eh.chunk_hashed = false;
            eh.ahead_err = null;
            ahead = std.Thread.spawn(.{}, prompt.engramReadAhead, .{ eh, c, seq, start, n, @as(usize, 0) }) catch null;
        }
    }
    m.rs.ahead = ahead;
}

fn sliceRun(m: *Model, seq: []const i32, args: ChunkArgs, lo: usize, hi: usize) !SliceEnd {
    const e = &m.eng;
    const c = e.c;
    const ch = &m.ch;
    const rs = &m.rs;
    if (hi <= lo or hi > c.layers) return error.BadSlice;
    if (lo == 0) {
        m.dropChunk();
        try m.openChunk(seq, args);
    } else if (!rs.live or rs.next != lo or seq.len != rs.args.start + rs.args.n) return error.BadSlice;
    const start = rs.args.start;
    const n = rs.args.n;
    const replay = rs.args.replay;
    const pt = m.ptimer;
    const taps = m.dr != null;
    for (lo..hi) |li| {
        if (li == c.layers / 2) {
            if (!try prompt.replayCut(e, ch, &m.view, &rs.shared, li, replay, m.host_pos)) {
                // encoder-only: no synchronize either (as at the chunk's end below), so the next chunk's host steps
                // run while this one's last layers do; the profile alone waits
                if (pt) |t| {
                    try m.stream.synchronize();
                    try t.finish();
                }
                prefill_prof.finish();
                m.rs.reset();
                return .encoder_only;
            }
            rs.floor = replay;
            rs.kv_done = li;
        }
        if (e.w.layers[li].engram_wkv != null) {
            const eh = if (m.eh) |*x| x else return error.NoEngramTables;
            if (rs.ahead) |th| {
                th.join();
                rs.ahead = null;
            }
            if (eh.ahead_err) |err| return err;
            const j = std.mem.indexOfScalar(u16, c.engram_layers.slice(), @intCast(li)).?;
            if (eh.lead_on) try m.lead.before(eh, j, start, n); // (TF_DS_ENGRAM_LEAD: this layer's reader)
            try prompt.engramApply(e, ch, eh, li, seq);
            const ne = @min(2, c.engram_layers.slice().len);
            if (eh.lead_on) {
                // this layer's rows of the next chunk from now, a whole chunk ahead of their layer
                const more = moreRowsAfter(m.fill_seq, seq, start, n);
                const nn = if (more) @min(chunk_rows, m.fill_seq.len - start - n) else 0;
                m.lead.after(eh, c, seq, start, n, j, if (more) m.fill_seq[0 .. start + n + nn] else null, nn);
            } else if (j + 1 < ne) {
                if (!eh.ahead_ready[j + 1])
                    rs.ahead = std.Thread.spawn(.{}, prompt.engramReadAhead, .{ eh, c, seq, start, n, j + 1 }) catch null;
            } else if (m.fill_seq.len > start + n and m.fill_seq.ptr == seq.ptr) {
                // the next chunk's rows while this one's layers run
                const nn = @min(chunk_rows, m.fill_seq.len - start - n);
                eh.ahead_start = start + n;
                eh.ahead_n = nn;
                eh.ahead_ready = .{ false, false };
                eh.chunk_hashed = false;
                eh.ahead_err = null;
                m.ahead = std.Thread.spawn(.{}, prompt.engramReadAheadAll, .{ eh, c, m.fill_seq[0 .. start + n + nn], start + n, nn }) catch null;
            }
            if (pt) |t| try t.mark(m.stream, .engram);
            prefill_prof.mark(m.stream, .engram);
        }
        // a DSpark tap reads the streams after the layer's Engram (_forward_k's order)
        if (taps) if (std.mem.indexOfScalar(u16, c.dspark_taps.slice(), @intCast(li))) |j| try prompt.tap(e, ch, j);
        try prompt.attnMixes(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .mix_attn);
        prefill_prof.mark(m.stream, .mix_attn);
        try prompt.attention(e, ch, &m.view, &rs.shared, li, m.ring_view[li], rs.floor, rs.kv_done != null and rs.kv_done.? == li);
        if (pt) |t| try t.mark(m.stream, .attn);
        prefill_prof.mark(m.stream, .attn);
        try prompt.gatherPartial(e, ch); // TF_DS_BF16_PARTIALS: bf16 on the wire, widened at the mixes
        if (pt) |t| try t.mark(m.stream, .gather_a);
        prefill_prof.mark(m.stream, .gather_a);
        try prompt.ffnMixes(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .mix_ffn);
        prefill_prof.mark(m.stream, .mix_ffn);
        try prompt.moe(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .moe);
        prefill_prof.mark(m.stream, .moe);
        // TF_DS_PREFILL_GATHER_OVERLAP: on the chunk's side stream (the next layer's Engram block overlaps it). The
        // phase mark below clocks the main stream's fork point then, not the gather: the chunk wall is the measure.
        try prompt.gatherAside(e, ch);
        if (pt) |t| try t.mark(m.stream, .gather_m);
        prefill_prof.mark(m.stream, .gather_m);
        prompt.endLayer(ch);
    }
    rs.next = hi;
    if (hi < c.layers) return .more;
    // TF_DS_HEAD_LAST_CHUNK (0188): only the pass's last chunk's head is the prompt's logits - an earlier chunk that
    // reached the decoder (the last window's rows straddling a chunk end) had it computed and thrown away, so its
    // fixed costs (collapse_norm, the head's own group, the gather) go. The chunk still returns .head: it reached the
    // head, it just had nothing to keep (fill_seq's test is the Engram read-ahead's "more rows after this chunk").
    if (!(m.head_last_chunk and moreRowsAfter(m.fill_seq, seq, start, n))) {
        try prompt.head(e, ch);
        if (pt) |t| try t.mark(m.stream, .head);
        prefill_prof.mark(m.stream, .head);
    }
    if (m.dr) |*dr| {
        // its taps (the tap layers side by side) into the slot's drafter rings
        const dw = c.hidden;
        for (0..c.dspark_taps.slice().len) |j| try e.ops.copyRows(e.s, prompt.tapRows(e, ch, j), dw * 2, dr.at + j * dw * 2, dr.taps_w * 2, dw * 2, ch.n);
        try dr.absorb(e, ch, &m.dpool.?, m.fill_slot, dr.at, ch.n, ch.start);
    }
    // no synchronize: the next chunk's host steps (its first Engram layer's hashing, table reads and decode, ~0.14 s
    // at 2,048 rows) run while this chunk's kernels do; readers of the results (the prompt's logits) synchronize.
    // The profile (--profile 2) times a chunk to its end, so it alone waits.
    if (pt) |t| {
        try m.stream.synchronize();
        try t.finish();
    }
    prefill_prof.finish();
    m.rs.reset();
    return .head;
}

/// The prompt's logits (its last row's, the ranks' columns in rank order) after a fill's last chunk.
pub fn promptLogits(m: *const Model) u64 {
    return m.ch.head_g;
}

/// One round over every stream's window (rows.windows, each with its stream's slot and extent): the forward,
/// and, in absorbRows, each window whose stream drafts has its rows' taps absorbed into its slot's drafter rings.
/// Split in two by 0160 so a round with TF_DS_ABSORB_AFTER_PICK runs the pick between them; without the switch
/// the callers keep the served order (forward, absorb, pick) and the same synchronizations.
pub fn verify(m: *Model, rows: round.Rows) !void {
    if (!m.aheadParked()) m.joinAhead(); // a prompt chunk's Engram read-ahead shares the host buffers a round's Engram reads use
    const e = &m.eng;
    if (m.prof) try m.stream.synchronize(); // (the GPU idle, so the issue time shows whether the host keeps it fed)
    const t0 = m.now();
    try round.forward(e, &m.rd, &m.ch, &m.caches, m.rings, if (m.eh) |*x| x else null, &.{}, rows, m.request_cap, null, if (m.graphs) |*g| g else null);
    if (m.prof) {
        m.t_enqueue = m.now() - t0;
        try m.stream.synchronize();
        m.t_forward = m.now() - t0;
        if (m.timer) |t| try t.finish();
        if (m.rd.clk != 0) {
            var h: [1 + 2 * round.Round.max_clocks]u64 = undefined;
            const d = m.ctx.d;
            try d.check(d.api.cuMemcpyDtoH_v2(&h, m.rd.clk, h.len * 8), "cuMemcpyDtoH");
            const n = @min(h[0], round.Round.max_clocks);
            for (1..n) |i| {
                const tag = h[2 + 2 * i] & 0xff;
                m.clk_ph[tag] += h[1 + 2 * i] -% h[1 + 2 * (i - 1)];
                m.clk_cnt[tag] += 1;
            }
            m.clk_rounds += 1;
        }
    }
}

/// The served eager absorb (0160, split out of verify): window i's rows' taps into its slot's drafter rings at
/// their positions (absorb[i]: the window's stream drafts; rows past the ones the round keeps sit where the
/// drafter never reads, and the next window overwrites them). With TF_DS_ABSORB_AFTER_PICK the kernels are left
/// running under the host's accept and the pass frame's send; the drafter pass, stream-ordered after them on the
/// same stream, sees them (bit-identical: the pick reads rd.logits and writes amax, the absorb reads rd.taps and
/// writes the drafter rings - independent kernels of one forward). Without the switch this returns with the
/// absorb done, as the round's old order had it.
pub fn absorbRows(m: *Model, rows: round.Rows, absorb: []const bool) !void {
    const e = &m.eng;
    const t1 = m.now();
    if (m.dr) |*dr| {
        const wins = rows.windows orelse return error.BadRound;
        var items: [max_streams]draft.Item = undefined;
        var n: usize = 0;
        for (wins, absorb) |win, yes| {
            if (!yes) continue;
            items[n] = .{ .slot = @intCast(rows.slots.?[win.row]), .taps = m.rd.taps + win.row * dr.taps_w * 2, .n = win.n, .start = @intCast(rows.pos[win.row]) };
            n += 1;
        }
        if (n > 0) try dr.absorbMany(e, &m.ch, &m.dpool.?, items[0..n]);
    }
    // the profile's absorb_ms wants the kernels finished (the late path then overlaps nothing); without the
    // profile and with the switch on, the kernels run under the host's accept and the pass frame's send
    if (!m.absorb_after_pick or m.prof) {
        try m.stream.synchronize();
        if (m.prof) m.t_absorb = m.now() - t1;
    }
}

/// The rounds' GPU clocks (a profile): the forward's start and each stretch's ends, for its gaps.
pub fn useClock(m: *Model, marks: u8) !void {
    m.rd.clk_marks = marks == 1 or marks == 3;
    m.rd.clk_shard = marks == 4; // the sharded attention's parts alone (round.PhaseTimer.shardMark)
    m.rd.clk_ratio = if (marks == 3) 2 else null;
    m.rd.clk_layers = marks == 2 or marks == 3;
    if (m.rd.clk == 0) m.rd.clk = try m.arena.take((1 + 2 * round.Round.max_clocks) * 8);
}

/// The rounds' GPU time by phase (eager rounds; --profile 2): a timer on the round.
