//! TF_DS_DRAFT_TAPS_DIRECT (off by default): the drafter reads a round's contiguous verify-round taps in place -
//! absorb_many's gather into dr.at is skipped when the participating windows' rows are consecutive in rd.taps, and
//! mainKeys reads the first row of the block directly (its input stride is the taps' row stride either way). Windows
//! with gaps keep the packing. Pure: no cuda import; the flag is Ops.draft_taps_direct and the arm is
//! Drafter.absorb_many. A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_DRAFT_TAPS_DIRECT";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadDraftTapsDirect}!bool {
    return parse(text) orelse error.BadDraftTapsDirect;
}

/// The in-place arm's first row: the windows' rows [taps[i], taps[i] + ns[i] * row_bytes) must be consecutive in the
/// given order (the caller's items are in round order, increasing), then the whole block is rows [first, first + sum
/// ns) at the row stride and the gather is skipped. A gap, an overlap or an out-of-order item keeps the packing (the
/// packed arm preserves the items' order either way).
pub fn inPlace(taps: []const u64, ns: []const usize, row_bytes: usize) ?u64 {
    if (taps.len == 0 or taps.len != ns.len) return null;
    for (0..taps.len - 1) |i| {
        if (taps[i + 1] != taps[i] + ns[i] * row_bytes) return null;
    }
    return taps[0];
}
```

