const ops_mod = @import("ops.zig");
const taps_direct = @import("draft_taps_direct.zig");
var conf_pack_noted = std.atomic.Value(bool).init(false);
var taps_direct_noted = std.atomic.Value(bool).init(false);

/// Drafter.absorb_many: every item's rows in one pass over the pool's planes (ring row slot * ring + position %
/// ring); the caller sets each slot's `absorbed` (eager: the kept length, known after sampling). TF_DS_DRAFT_TAPS_DIRECT:
/// items whose rows are consecutive in rd.taps are read in place (no gather into dr.at); gaps keep the packing.
pub fn absorbMany(dr: *Drafter, e: *const Engine, ch: *const Chunk, pool: *const Pool, items: []const Item) !void {
    var n: usize = 0;
    var pos: [max_absorb]i64 = undefined;
    var rows: [max_absorb]i64 = undefined;
    // TF_DS_DRAFT_TAPS_DIRECT: the in-place arm when the items (the round's windows in round order) hold
    // consecutive taps rows - decided here per round at enqueue time, outside every captured graph
    var direct: ?u64 = null;
    if (e.ops.draft_taps_direct and items.len <= max_streams) {
        var taps: [max_streams]u64 = undefined;
        var ns: [max_streams]usize = undefined;
        for (items, 0..) |it, i| {
            taps[i] = it.taps;
            ns[i] = it.n;
        }
        direct = taps_direct.inPlace(taps[0..items.len], ns[0..items.len], dr.taps_w * 2);
    }
    for (items) |it| {
        if (it.slot >= pool.slots or n + it.n > max_absorb) return error.BadAbsorb;
        if (direct == null) try e.ops.copyRows(e.s, it.taps, dr.taps_w * 2, dr.at + n * dr.taps_w * 2, dr.taps_w * 2, dr.taps_w * 2, it.n);
        for (0..it.n) |r| {
            const p = it.start + r;
            pos[n + r] = @intCast(p);
            rows[n + r] = @intCast(it.slot * pool.ring + p % pool.ring);
        }
        n += it.n;
    }
    if (n == 0) return;
    try prompt.upload(e, dr.apos, &pos, n * 8);
    try prompt.upload(e, dr.arows, &rows, n * 8);
    if (direct) |taps| {
        if (!taps_direct_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_DRAFT_TAPS_DIRECT: the drafter reads the round's contiguous taps rows in place (first at {d} windows x {d} rows)", .{ items.len, n });
        try dr.mainKeys(e, ch, taps, n);
    } else try dr.mainKeys(e, ch, dr.at, n);

